@app.route("/health", methods=["GET"])
def health():
    """Liveness + per-slot state. Contract notes are inline below; the
    field set is consumed by the web UI status dot and external launchers.
    ``provenance`` is the runtime/driver/flags block benchmark.py copies into
    every results file (build_provenance)."""
    devices = {}
    if primary and primary.status != "not_configured":
        devices[primary.device_name.lower()] = primary.info
    if secondary and secondary.status != "not_configured":
        devices[secondary.device_name.lower()] = secondary.info
    # prompt_cache stays a bare bool — launcher health checks truth-test
    # it; the details live in prompt_cache_info (per-slot TTFT
    # and prewarm state are in each device's info block).
    result = {"status": overall_status(), "version": __version__,
              "devices": devices,
              "provenance": PROVENANCE,
              "prompt_cache": PROMPT_CACHE,
              "prompt_cache_info": {
                  "enabled": PROMPT_CACHE,
                  # pinned --cache-size-gb value; null = auto-sized (the
                  # resolved size is per-slot: devices[*].kv_pool_gb)
                  "pool_gb": PROMPT_CACHE_GB,
                  "auto": PROMPT_CACHE_GB is None,
                  "prewarm_file": PREWARM_FILE,
              }}
    if whisper_slot and whisper_slot.status != "not_configured":
        result["whisper"] = whisper_slot.info
    if embed_slot and embed_slot.status != "not_configured":
        result["embed"] = embed_slot.info
    return jsonify(result)


@app.route("/v1/models", methods=["GET"])
def list_models():
    """OpenAI model list. Ids are "name@DEVICE" so a dual-mode setup exposes
    both slots distinctly; _route_request accepts either form back.

    Whisper ("whisper@DEVICE") and the embedder (bare name) are listed too,
    for API clients. The web UI's chat picker (loadModels) keeps only ids of
    the form f"{info['model']}@{info['device_name']}" from /health's
    `devices`, so a slot that cannot chat must report outside `devices`
    (as whisper and embed do), and these two id shapes must stay in step.
    """
    data = []
    for slot in (primary, secondary):
        if slot and slot.status == "ready":
            data.append({
                "id": f"{slot.model_name}@{slot.device_name}",
                "object": "model",
                "created": 0,
                "owned_by": f"local-{slot.device_name.lower()}",
            })
    if whisper_slot and whisper_slot.status == "ready":
        data.append({
            "id": f"whisper@{whisper_slot.device_name}",
            "object": "model",
            "created": 0,
            "owned_by": f"local-{whisper_slot.device_name.lower()}",
        })
    if embed_slot and embed_slot.status == "ready":
        # Bare name, no @DEVICE: unlike the generative slots this one is never
        # routed to by name (there is only one), and a RAG client looks its
        # embedding model up by the exact string it has hard-coded.
        data.append({
            "id": embed_slot.model_name,
            "object": "model",
            "created": 0,
            "owned_by": f"local-{embed_slot.device_name.lower()}",
        })
    return jsonify({"object": "list", "data": data})


def _embed_inputs(body):
    """Pull the texts out of whichever embedding request shape arrived.

    Why: the three clients that matter disagree. OpenAI sends `input` as a
    string or a list, current Ollama sends `input`, pre-0.3 Ollama sends
    `prompt` as a single string, and LangChain-shaped callers send `text`.
    Accepting all four costs four lines and removes a whole class of
    "returns 400 and the index stays empty" reports.

    In: the parsed JSON body. Out: a list of strings, empty when the body
    carries no recognizable input (the caller turns that into a 400).
    """
    value = body.get("input", body.get("prompt", body.get("text")))
    if value is None:
        return []
    if isinstance(value, str):
        return [value]
    if not isinstance(value, (list, tuple)):
        return [str(value)]

